import { onUnmounted } from "vue";
//#region src/value/use-motion-value-event.ts
/**
* 监听 MotionValue 的事件
* @param value MotionValue 实例
* @param event 事件名称
* @param callback 回调函数
*/
function useMotionValueEvent(value, event, callback) {
	const unlisten = value.on(event, callback);
	onUnmounted(() => {
		unlisten();
	});
	return unlisten;
}
//#endregion
export { useMotionValueEvent };
